// AI coaching feedback on a practice transcript, generated by Claude.
import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";
import { betaZodOutputFormat } from "@anthropic-ai/sdk/helpers/beta/zod";

const MODEL = process.env.FEEDBACK_MODEL || "claude-opus-5-5";
// Coaching replies are short and someone is waiting to hear them, so default to low effort.
const EFFORT = process.env.FEEDBACK_EFFORT || "low";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY

export const Feedback = z.object({
  score: z.number().int().describe("Overall delivery score from 0 to 100"),
  summary: z.string().describe("One sentence on how it went overall"),
  strengths: z.array(z.string()).describe("1-3 specific things they did well, quoting their words where possible"),
  improvements: z.array(z.string()).describe("1-3 specific, actionable changes for next time"),
  rewrite: z.string().describe("A stronger version of one sentence they said, in their own voice"),
  spoken: z
    .string()
    .describe("A warm 2-4 sentence message to be read aloud to them by a voice coach. Plain speech only: no lists, emoji, markdown or symbols."),
});

const SYSTEM = `You are the speaking coach inside Outspoken, an app that helps people build social confidence.
The user just practised speaking out loud for a scenario. You get the scenario prompt, an automatic speech-to-text transcript, and measured delivery stats.

How to coach:
- Be warm, direct and specific. Sound like an encouraging friend who happens to be a great coach, never a grader.
- Ground every point in what they actually said. Quote short phrases.
- Judge content (clarity, structure, confidence of language, warmth, fit for the scenario) and delivery (pace, filler words, hedging) using the stats provided.
- The transcript comes from speech recognition, so ignore missing punctuation and obvious mis-transcriptions.
- If the transcript is very short or empty, encourage them to try again and give one simple tip.
- This is coaching, not therapy. If the user expresses distress or thoughts of self-harm, respond kindly and suggest talking to someone they trust or a local crisis line.
- The "spoken" field is read aloud by a text-to-speech voice: write natural spoken sentences, address them as "you", and keep it under 70 words.`;

/**
 * @param {{ scenario: string, prompt: string, transcript: string, seconds: number, wpm: number, fillers: number, hedges: number, name?: string }} input
 */
export async function getFeedback(input) {
  const stats = `Duration: ${Math.round(input.seconds)}s · Pace: ${input.wpm} words/min · Filler words: ${input.fillers} · Hedging phrases: ${input.hedges}`;
  const userText = [
    input.name ? `Speaker's first name: ${input.name}` : null,
    `Scenario: ${input.scenario}`,
    `Prompt they were given: ${input.prompt}`,
    `Delivery stats: ${stats}`,
    `Transcript:\n<transcript>\n${input.transcript || "(nothing was transcribed)"}\n</transcript>`,
  ]
    .filter(Boolean)
    .join("\n\n");

  const response = await client.beta.messages.parse({
    model: MODEL,
    max_tokens: 16000,
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",
    output_config: { effort: EFFORT, format: betaZodOutputFormat(Feedback) },
    system: SYSTEM,
    messages: [{ role: "user", content: userText }],
  });

  if (response.stop_reason === "refusal") {
    const err = new Error("The coach couldn't respond to this one. Try another practice run.");
    err.status = 422;
    throw err;
  }
  if (!response.parsed_output) {
    const err = new Error("The coach's reply couldn't be read. Please try again.");
    err.status = 502;
    throw err;
  }
  const out = response.parsed_output;
  out.score = Math.max(0, Math.min(100, out.score));
  return out;
}

export { Anthropic };
